def ikon(nama: str, ukuran: int = 18, warna: str = "#3D4B46", tebal: float = 2) -> str:
    """Ikon sebagai <img> SVG data-URI. st.html membuang <svg> inline, tetapi <img> data-URI lolos.
    Dekoratif (alt kosong); arti selalu disertai teks di sebelahnya."""
    svg = (f'<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" '
           f'stroke="{warna}" stroke-width="{tebal}" stroke-linecap="round" stroke-linejoin="round">'
           f'{_IKON[nama]}</svg>')
    return (f'<img class="tp-ikon" src="data:image/svg+xml;base64,{base64.b64encode(svg.encode()).decode()}" '
            f'width="{ukuran}" height="{ukuran}" alt="">')
